export type SeoIllustration = {
  /** Alt с точным вхождением целевого запроса (Google Images). */
  alt: string;
  /** Полная подпись для figcaption (sr-only) и JSON-LD. */
  caption: string;
  /** Короткий chip на экране (1–3 слова). */
  label: string;
  /** Стабильный источник фото из каталога. */
  cardSlug?: string;
  /** Подстрока в title_ru для поиска в кластере, если cardSlug не задан. */
  titleIncludes?: string;
};

export type SeoPopularLink = {
  label: string;
  href: string;
};

export type SeoTextBlock = {
  h2: string;
  paragraphs: string[];
};

export type SeoContent = {
  h1: string;
  metaTitle: string;
  metaDescription: string;
  intro: string;
  faqItems: { q: string; a: string }[];
  howToSteps: string[];
  /** 0–4 SEO-иллюстрации с alt под запросы (пилот L1). */
  illustrations?: SeoIllustration[];
  /** Keyword-rich перелинковка на L2/L1 (пилот devushka). */
  popularLinks?: SeoPopularLink[];
  /** Порядок L2 chips по search volume (slug из TAG_REGISTRY). */
  featuredL2Slugs?: string[];
  /** Кастомный H2 блока «Как использовать промт» (ключ в заголовке). */
  howToTitle?: string;
  /** SEO-текст после FAQ: H2 + абзацы (текстовая релевантность L1). */
  seoTextBlocks?: SeoTextBlock[];
  /** H2 над поиском и сеткой, когда H1 уехал в hero (шаблон главной). */
  explorerTitle?: string;
  explorerIntro?: string;
};

